    "code": "    double hx = 0.5;\n    double hy = 0.5;\n    double hz = 0.5;\n    std::vector<Point> verts = {\n        Point(-hx, -hy, -hz),\n        Point(hx, -hy, -hz),\n        Point(hx, hy, -hz),\n        Point(-hx, hy, -hz),\n        Point(-hx, -hy, hz),\n        Point(hx, -hy, hz),\n        Point(hx, hy, hz),\n        Point(-hx, hy, hz),\n    };\n    std::vector<std::vector<size_t>> faces = {\n        {0, 3, 2, 1},\n        {4, 5, 6, 7},\n        {0, 1, 5, 4},\n        {2, 3, 7, 6},\n        {0, 4, 7, 3},\n        {1, 2, 6, 5},\n    };\n\n    Mesh mesh = Mesh();\n\n    for (const Point& v : verts)\n        mesh.add_vertex(v);\n\n    for (const std::vector<size_t>& f : faces)\n        mesh.add_face(f);\n\n\n    mesh.remove_vertex(0);\n\n\n    mesh.remove_edge(1, 2);\n\n\n    mesh.remove_face(1);\n\n\n    mesh.clear();\n\n\n    for (const Point& v : verts)\n        mesh.add_vertex(v);\n\n    for (const std::vector<size_t>& f : faces)\n        mesh.add_face(f);\n\n    mesh = mesh.unweld();\n\n\n    mesh = mesh.weld(0.001);\n\n\n    std::vector<size_t> fv0 = *mesh.face_vertices(0);\n    std::vector<size_t> fv1 = *mesh.face_vertices(1);\n    std::vector<size_t> fv2 = *mesh.face_vertices(2);\n    std::vector<size_t> fv3 = *mesh.face_vertices(3);\n    std::vector<size_t> fv4 = *mesh.face_vertices(4);\n    std::vector<size_t> fv5 = *mesh.face_vertices(5);\n\n\n    mesh.flip_face(0);\n    fv0 = *mesh.face_vertices(0);\n    fv1 = *mesh.face_vertices(1);\n    fv2 = *mesh.face_vertices(2);\n    fv3 = *mesh.face_vertices(3);\n    fv4 = *mesh.face_vertices(4);\n    fv5 = *mesh.face_vertices(5);\n\n\n    mesh.unify_winding();\n    fv0 = *mesh.face_vertices(0);\n    fv1 = *mesh.face_vertices(1);\n    fv2 = *mesh.face_vertices(2);\n    fv3 = *mesh.face_vertices(3);\n    fv4 = *mesh.face_vertices(4);\n    fv5 = *mesh.face_vertices(5);\n\n\n    mesh.flip();\n    fv0 = *mesh.face_vertices(0);\n    fv1 = *mesh.face_vertices(1);\n    fv2 = *mesh.face_vertices(2);\n    fv3 = *mesh.face_vertices(3);\n    fv4 = *mesh.face_vertices(4);\n    fv5 = *mesh.face_vertices(5);\n\n\n    mesh.orient_outward();\n    fv0 = *mesh.face_vertices(0);\n    fv1 = *mesh.face_vertices(1);\n    fv2 = *mesh.face_vertices(2);\n    fv3 = *mesh.face_vertices(3);\n    fv4 = *mesh.face_vertices(4);\n    fv5 = *mesh.face_vertices(5);",
