    "passed": true,
    "time_ms": 5.756,
    "line": 137,
    "code": "    const NurbsSurface planar = NurbsSurface::create(\n        false,\n        false,\n        1,\n        1,\n        2,\n        2,\n        {\n            Point(0.0, 0.0, 0.0),\n            Point(0.0, 4.0, 0.0),\n            Point(4.0, 0.0, 0.0),\n            Point(4.0, 4.0, 0.0),\n        }\n    );\n\n    for (const NurbsSurface& surface : {planar, Primitives::wave_surface(1.0, 0.5)}) {\n        NurbsSurfaceTrimmed ts;\n        ts.m_surface = surface;\n        TrimLoops loops;\n\n        for (const std::pair<double, double>& range : {std::pair<double, double>{0.0, 1.0}, {0.25, 0.75}}) {\n            const double low = range.first;\n            const double high = range.second;\n            std::vector<Point> uv;\n            std::vector<Point> xyz;\n            std::vector<std::pair<double, double>> corners = {{low, low}, {high, low}, {high, high}, {low, high}};\n\n            for (size_t side = 0; side < 4; ++side) {\n                const std::pair<double, double> a = corners[side];\n                const std::pair<double, double> b = corners[(side + 1) % 4];\n\n                for (int sample = 0; sample < 8; ++sample) {\n                    double t = sample / 8.0;\n                    uv.push_back(Point(a.first + t * (b.first - a.first), a.second + t * (b.second - a.second), 0.0));\n                }\n            }\n\n            for (const Point& p : uv)\n                xyz.push_back(ts.m_surface.point_at(p[0], p[1]));\n\n            loops.uv.push_back(uv);\n            loops.xyz.push_back(xyz);\n        }\n\n        Mesh mesh = ts.mesh_loops(loops, 20.0, 0.005);\n\n\n        for (size_t li = 0; li < loops.xyz.size(); ++li) {\n            const std::vector<Point>& points = loops.xyz[li];\n\n            for (size_t sample = 0; sample < points.size(); ++sample) {\n                const Point& p = points[sample];\n                std::string key = \"boundary/\" + std::to_string(li) + \"/\" + std::to_string(sample);\n                bool found = false;\n\n                for (const std::pair<const size_t, VertexData>& entry : mesh.vertex) {\n                    const VertexData& vd = entry.second;\n\n                    if (vd.attributes.count(key)) {\n\n                        found = true;\n                        break;\n                    }\n                }\n\n            }\n        }\n\n        for (const std::pair<const size_t, std::vector<size_t>>& entry : mesh.face) {\n            const std::vector<size_t>& vertices = entry.second;\n            double u = 0.0;\n            double v = 0.0;\n\n            for (size_t key : vertices) {\n                u += mesh.vertex[key].attributes[\"u\"];\n                v += mesh.vertex[key].attributes[\"v\"];\n            }\n\n            u /= vertices.size();\n            v /= vertices.size();\n\n        }\n\n        loops.xyz[0].pop_back();",
